/**
 * The tags of a single instance keyed by tag name, or `undefined` when the
 * instance is not there any more. Instances come and go, so a caller walking
 * instance metadata treats a missing instance as a dead end rather than an
 * error.
 */
export const getInstanceTags = async (region, creds, instanceId: string): Promise<Record<string, string>> => {
    const ec2Client = new EC2Client({ region, credentials: creds });
    try {
        const { Reservations } = await ec2Client.send(
            new DescribeInstancesCommand({ InstanceIds: [instanceId] }),
        );
        const [instance] = (Reservations ?? []).flatMap(({ Instances }) => Instances ?? []);
        if (!instance) {
            return undefined;
        }
        return (instance.Tags ?? []).reduce((tags, { Key, Value }) => {
            if (Key) {
                tags[Key] = Value;
            }
            return tags;
        }, {} as Record<string, string>);
    } catch (error) {
        if (error?.name === 'InvalidInstanceID.NotFound' || error?.Code === 'InvalidInstanceID.NotFound') {
            return undefined;
        }
        throw error;
    }
};
