import { getDocument } from '../../utils/aws/s3.js';
import { getParameterValue } from '../../utils/aws/awsSSM.js';
import { getInstanceTags } from '../../utils/aws/awsEc2.js';
import { MeteredAccount, MeteringRegistry, credentialsForAccount } from './meteringAccounts.entity.js';

const POOL_REFERENCE = 'pool/';
const UNIT_REFERENCE = 'unit/';
const ALIAS_REFERENCE = 'alias/';
const NODE_REFERENCE = 'node/';

/** Where the aliases a business has published live. */
const ALIAS_PARAMETER_PREFIX = '/paigo/attribution/alias/';
/** The tag an instance names its own charge code with. */
const NODE_CHARGE_CODE_TAG = 'paigoChargeCode';
/** The tag an instance passes its cost on with. */
const NODE_PASS_THROUGH_TAG = 'paigoRollsInto';

/**
 * One pocket of a business' estate. The finance system rewrites the whole set
 * whenever a team moves, so the pools are kept together in a single document
 * rather than one object each.
 */
export class AttributionPool {
    /** The code spend sitting on this pool is booked to. */
    public chargeCode: string;
    /**
     * Where this pool hands its cost on to, when it does not keep it. Pools
     * that keep their own cost leave this empty.
     * @example "unit/fernlea"
     */
    public rollsUpTo?: string;
}

export class AttributionPoolDocument {
    public revision: string;
    public pools: Record<string, AttributionPool>;
}

/**
 * A business unit. Units are written one object each because the systems that
 * own them are not the system that owns the pools.
 */
export class AttributionUnit {
    public unitId: string;
    /** The code spend sitting on this unit is booked to. */
    public chargeCode: string;
    /**
     * Where this unit hands its cost on to, when it does not keep it.
     * @example "node/310000000028/us-east-1/i-06e9b1c504ab8b1d0"
     */
    public parentRef?: string;
}

/**
 * One step of an attribution chain: the code the step would book spend to and
 * where, if anywhere, the step hands that spend on to.
 */
export class AttributionStep {
    /** The reference this step was reached by. */
    public reference: string;
    /** The code named at this step, when the step names one. */
    public chargeCode?: string;
    /** The next reference in the chain, when the step passes its cost on. */
    public passesTo?: string;
}

/**
 * The charge code carried by every reference of a repeating chain, which is the
 * code the whole cycle agrees on. When the members of a cycle disagree the code
 * most of them carry is used, so a single mistyped link cannot move a cycle's
 * spend somewhere unrelated.
 */
const sharedChargeCode = (steps: Array<AttributionStep>): string => {
    const counts = new Map<string, number>();
    steps.forEach(({ chargeCode }) => {
        if (chargeCode) {
            counts.set(chargeCode, (counts.get(chargeCode) ?? 0) + 1);
        }
    });
    const [shared] = [...counts.entries()].sort(
        ([leftCode, leftCount], [rightCode, rightCount]) => rightCount - leftCount || leftCode.localeCompare(rightCode),
    );
    return shared?.[0];
};

/**
 * The attribution material a business keeps beside its onboarding record.
 *
 * A usage line names where in that material it starts, and a reference is free
 * to hand its cost on to another reference. Every reference kind can pass cost
 * on to any other kind, so following a line to the code that finally carries it
 * means walking the chain rather than reading the first hop.
 */
export class AttributionDirectory {
    private readonly bucket: string;
    private readonly prefix: string;
    private readonly pools: Record<string, AttributionPool>;
    private readonly accounts: Record<string, MeteredAccount>;
    private readonly credentials = new Map<string, ReturnType<typeof credentialsForAccount>>();
    private readonly steps = new Map<string, Promise<AttributionStep>>();
    private readonly finalCodes = new Map<string, Promise<string>>();

    private constructor(
        bucket: string,
        prefix: string,
        pools: Record<string, AttributionPool>,
        accounts: Array<MeteredAccount>,
    ) {
        this.bucket = bucket;
        this.prefix = prefix;
        this.pools = pools;
        this.accounts = (accounts ?? []).reduce((byId, account) => {
            byId[account.accountId] = account;
            return byId;
        }, {} as Record<string, MeteredAccount>);
    }

    /**
     * Loads the material a business keeps under the given prefix. The registry
     * is needed because part of the material lives on the resources of the
     * business' own accounts, which are only readable through their roles.
     */
    static async load(bucket: string, prefix: string, registry?: MeteringRegistry): Promise<AttributionDirectory> {
        const document = await getDocument<AttributionPoolDocument>(bucket, `${prefix}pools.json`);
        return new AttributionDirectory(bucket, prefix, document?.pools ?? {}, registry?.accounts ?? []);
    }

    /**
     * The charge code that finally carries the spend of a usage line, having
     * followed every hand off the line's reference makes. Intermediate codes
     * along the way are not the answer: only the end of the chain is.
     *
     * A chain that repeats has no end, so the code shared by the repeating
     * references is used instead. A chain that runs into material that is not
     * there falls back to the last code it did see.
     */
    async chargeCodeFor(reference: string): Promise<string> {
        if (!reference) {
            return undefined;
        }
        if (!this.finalCodes.has(reference)) {
            this.finalCodes.set(reference, this.walk(reference));
        }
        return this.finalCodes.get(reference);
    }

    /**
     * The charge code named by the reference itself, ignoring any hand off it
     * makes. Useful when reporting on the material rather than on spend.
     */
    async immediateChargeCodeFor(reference: string): Promise<string> {
        const step = await this.resolve(reference);
        return step?.chargeCode;
    }

    /**
     * Follows a chain of references to its end.
     */
    private async walk(reference: string): Promise<string> {
        const walked: Array<AttributionStep> = [];
        const visited = new Map<string, number>();
        let current = reference;

        while (current) {
            if (visited.has(current)) {
                // The chain repeats: the references from the first sighting of
                // this one onwards are the cycle, and they share a code.
                return sharedChargeCode(walked.slice(visited.get(current)));
            }
            visited.set(current, walked.length);
            // Each hop has to be read before we know where it points.
            // eslint-disable-next-line no-await-in-loop
            const step = await this.resolve(current);
            if (!step) {
                break;
            }
            walked.push(step);
            current = step.passesTo;
        }

        return [...walked].reverse().find(({ chargeCode }) => Boolean(chargeCode))?.chargeCode;
    }

    /**
     * Reads a single reference of any kind.
     */
    private async resolve(reference: string): Promise<AttributionStep> {
        if (!reference) {
            return undefined;
        }
        if (!this.steps.has(reference)) {
            this.steps.set(reference, this.read(reference));
        }
        return this.steps.get(reference);
    }

    private async read(reference: string): Promise<AttributionStep> {
        if (reference.startsWith(POOL_REFERENCE)) {
            return this.readPool(reference);
        }
        if (reference.startsWith(UNIT_REFERENCE)) {
            return this.readUnit(reference);
        }
        if (reference.startsWith(ALIAS_REFERENCE)) {
            return this.readAlias(reference);
        }
        if (reference.startsWith(NODE_REFERENCE)) {
            return this.readNode(reference);
        }
        return undefined;
    }

    private readPool(reference: string): AttributionStep {
        const pool = this.pools[reference.slice(POOL_REFERENCE.length)];
        if (!pool) {
            return undefined;
        }
        return { reference, chargeCode: pool.chargeCode, passesTo: pool.rollsUpTo };
    }

    private async readUnit(reference: string): Promise<AttributionStep> {
        const unit = await this.readDocument<AttributionUnit>(
            `${this.prefix}units/${reference.slice(UNIT_REFERENCE.length)}.json`,
        );
        if (!unit) {
            return undefined;
        }
        return { reference, chargeCode: unit.chargeCode, passesTo: unit.parentRef };
    }

    private async readAlias(reference: string): Promise<AttributionStep> {
        const target = await getParameterValue(`${ALIAS_PARAMETER_PREFIX}${reference.slice(ALIAS_REFERENCE.length)}`);
        if (!target) {
            return undefined;
        }
        // An alias is only a pointer, it never carries spend of its own.
        return { reference, passesTo: target };
    }

    private async readNode(reference: string): Promise<AttributionStep> {
        const [accountId, region, ...rest] = reference.slice(NODE_REFERENCE.length).split('/');
        const instanceId = rest.join('/');
        if (!accountId || !region || !instanceId) {
            return undefined;
        }
        const account = this.accounts[accountId];
        if (!account) {
            return undefined;
        }
        const tags = await getInstanceTags(region, this.credentialsFor(account), instanceId);
        if (!tags) {
            return undefined;
        }
        return {
            reference,
            chargeCode: tags[NODE_CHARGE_CODE_TAG],
            passesTo: tags[NODE_PASS_THROUGH_TAG],
        };
    }

    private credentialsFor(account: MeteredAccount) {
        if (!this.credentials.has(account.accountId)) {
            this.credentials.set(account.accountId, credentialsForAccount(account));
        }
        return this.credentials.get(account.accountId);
    }

    private async readDocument<T>(key: string): Promise<T> {
        try {
            return await getDocument<T>(this.bucket, key);
        } catch (error) {
            if (error?.name === 'NoSuchKey' || error?.Code === 'NoSuchKey' || error?.name === 'NotFound') {
                return undefined;
            }
            throw error;
        }
    }
}
