        });
        const directory = await AttributionDirectory.load(BUCKET, PREFIX, registry);

        await expect(directory.chargeCodeFor('pool/quarry')).resolves.toEqual('cc-config-svc');
    });

    it('ignores references it cannot make sense of', async () => {
        givenMaterial({ pools: { aurora: { chargeCode: 'cc-platform-core' } } });
        const directory = await AttributionDirectory.load(BUCKET, PREFIX, registry);

        await expect(directory.chargeCodeFor('pool/missing')).resolves.toBeUndefined();
        await expect(directory.chargeCodeFor('something/else')).resolves.toBeUndefined();
        await expect(directory.chargeCodeFor(undefined)).resolves.toBeUndefined();
        await expect(directory.chargeCodeFor('node/999999999999/us-east-1/i-01')).resolves.toBeUndefined();
    });

    it('reads each reference of a chain once, however many lines start from it', async () => {
        givenMaterial({
            pools: { lantern: { chargeCode: 'cc-log-shipping', rollsUpTo: 'alias/upwell' } },
            units: { marlin: { chargeCode: 'cc-media-encode' } },
            aliases: { upwell: 'unit/marlin' },
